import { createServer } from 'node:http'
import { gunzipSync } from 'node:zlib'
import { afterEach, describe, expect, it, vi } from 'vitest'
import { PostHogPlugin } from './index.js'

type AnyEvent = { type: string; properties: Record<string, unknown> }

const originalEnv = {
    apiKey: [REDACTED],
    enabled: process.env.POSTHOG_ENABLED,
    host: process.env.POSTHOG_HOST,
    timezone: process.env.TZ,
}

afterEach(() => {
    vi.useRealTimers()
    for (const [key, value] of Object.entries({
        POSTHOG_API_KEY: [REDACTED],
        POSTHOG_ENABLED: originalEnv.enabled,
        POSTHOG_HOST: originalEnv.host,
        TZ: originalEnv.timezone,
    })) {
        if (value === undefined) delete process.env[key]
        else process.env[key] = value
    }
})

describe('event timestamps', () => {
    it('lets posthog-node add an exact UTC timestamp to the serialized event', async () => {
        process.env.TZ = 'America/Los_Angeles'
        const localTime = new Date(2024, 6, 1, 12, 34, 56, 789)
        expect(localTime.getTimezoneOffset()).toBe(420)
        vi.useFakeTimers({ toFake: ['Date'] })
        vi.setSystemTime(localTime)

        const bodies: Buffer[] = []
        const server = createServer((request, response) => {
            const chunks: Buffer[] = []
            request.on('data', (chunk: Buffer) => chunks.push(chunk))
            request.on('end', () => {
                const body = Buffer.concat(chunks)
                bodies.push(request.headers['content-encoding'] === 'gzip' ? gunzipSync(body) : body)
                response.writeHead(200, { 'content-type': 'application/json' })
                response.end('{}')
            })
        })
        await new Promise<void>((resolve) => server.listen(0, '127.0.0.1', resolve))

        try {
            const address = server.address()
            if (!address || typeof address === 'string') throw new Error('Expected TCP server address')
            process.env.POSTHOG_API_KEY = 'phc_test'
            process.env.POSTHOG_ENABLED = 'true'
            process.env.POSTHOG_HOST = `http://127.0.0.1:${address.port}`

            const hooks = (await PostHogPlugin({} as never)) as {
                event: (input: { event: AnyEvent }) => Promise<void>
                dispose: () => Promise<void>
            }
            const sessionID = 'session-timestamp'
            const messageID = 'message-timestamp'

            await hooks.event({
                event: {
                    type: 'message.updated',
                    properties: {
                        info: {
                            role: 'assistant',
                            id: messageID,
                            sessionID,
                            modelID: 'test-model',
                            providerID: 'test-provider',
                        },
                    },
                },
            })
            await hooks.event({
                event: {
                    type: 'message.part.updated',
                    properties: {
                        part: {
                            type: 'step-finish',
                            sessionID,
                            messageID,
                            tokens: { input: 1, output: 1, reasoning: 0, cache: { read: 0, write: 0 } },
                            cost: 0,
                            reason: 'stop',
                        },
                    },
                },
            })
            await hooks.dispose()

            expect(bodies).toHaveLength(1)
            const payload = JSON.parse(bodies[0].toString()) as {
                sent_at: string
                batch: Array<{ event: string; timestamp: string }>
            }
            expect(payload.sent_at).toBe('2024-07-01T19:34:56.789Z')
            expect(payload.batch).toHaveLength(1)
            expect(payload.batch[0]).toMatchObject({
                event: '$ai_generation',
                timestamp: '2024-07-01T19:34:56.789Z',
            })
        } finally {
            await new Promise<void>((resolve, reject) => server.close((error) => (error ? reject(error) : resolve())))
        }
    })
})

import { describe, it, expect, beforeEach, vi } from 'vitest'

// Capture everything the plugin sends, without touching the network.
const captured: Array<{ event: string; properties: Record<string, unknown> }> = []

vi.mock('posthog-node', () => ({
    PostHog: class {
        capture(e: { event: string; properties: Record<string, unknown> }) {
            captured.push(e)
        }
        async flush() {}
        async shutdown() {}
    },
}))

import { PostHogPlugin } from './index.js'

type AnyEvent = { type: string; properties: Record<string, unknown> }

async function run(events: AnyEvent[]) {
    process.env.POSTHOG_API_KEY = 'phc_test'
    const hooks = (await PostHogPlugin({} as never)) as { event: (i: { event: AnyEvent }) => Promise<void> }
    // oxlint-disable-next-line no-await-in-loop -- Event order is significant.
    for (const event of events) await hooks.event({ event })
}

const S = 'ses_test'
const U = 'msg_user_1'
const A = 'msg_asst_1'

beforeEach(() => {
    captured.length = 0
})

describe('trace state machine (real OpenCode event ordering)', () => {
    it('captures input and model even when the user message.updated repeats (regression: trace reset)', async () => {
        // OpenCode emits message.updated for the same user message several times
        // per turn. A repeat must not reset the trace and wipe accumulated state.
        await run([
            {
                type: 'message.updated',
                properties: { info: { role: 'user', id: U, sessionID: S, time: { created: 1 }, agent: 'build' } },
            },
            {
                type: 'message.part.updated',
                properties: { part: { type: 'text', messageID: U, sessionID: S, text: 'tell me a joke' } },
            },
            {
                type: 'message.updated',
                properties: {
                    info: {
                        role: 'assistant',
                        id: A,
                        sessionID: S,
                        modelID: 'gpt-5.4-mini',
                        providerID: 'openai',
                        time: { created: 1 },
                    },
                },
            },
            // duplicate user update — previously reset the trace
            {
                type: 'message.updated',
                properties: { info: { role: 'user', id: U, sessionID: S, time: { created: 1 }, agent: 'build' } },
            },
            { type: 'message.part.updated', properties: { part: { type: 'step-start', sessionID: S, messageID: A } } },
            {
                type: 'message.part.updated',
                properties: {
                    part: { type: 'text', messageID: A, sessionID: S, text: 'Because light attracts bugs.' },
                },
            },
            {
                type: 'message.part.updated',
                properties: {
                    part: {
                        type: 'step-finish',
                        sessionID: S,
                        messageID: A,
                        tokens: { input: 22436, output: 18, reasoning: 0, cache: { read: 0, write: 0 } },
                        cost: 0,
                        reason: 'stop',
                    },
                },
            },
            // another duplicate user update after step-finish
            {
                type: 'message.updated',
                properties: { info: { role: 'user', id: U, sessionID: S, time: { created: 1 }, agent: 'build' } },
            },
            { type: 'session.idle', properties: { sessionID: S } },
        ])

        const gen = captured.find((e) => e.event === '$ai_generation')
        const trace = captured.find((e) => e.event === '$ai_trace')

        expect(gen).toBeDefined()
        expect(gen!.properties.$ai_model).toBe('gpt-5.4-mini')
        expect(gen!.properties.$ai_provider).toBe('openai')
        expect(gen!.properties.$ai_input).toEqual([{ role: 'user', content: 'tell me a joke' }])

        expect(trace).toBeDefined()
        expect(trace!.properties.$ai_input_state).toBe('tell me a joke')

        // exactly one trace per user message (no duplicate traces from repeats)
        expect(captured.filter((e) => e.event === '$ai_trace')).toHaveLength(1)
    })

    it("attributes each step's tool calls in invocation order when parallel tools finish out of order", async () => {
        // Two steps: the first calls parallel tools, the second answers from their results.
        const tool = (name: string, id: string, status: 'running' | 'completed') => ({
            type: 'message.part.updated',
            properties: {
                part: {
                    type: 'tool',
                    id,
                    callID: id,
                    sessionID: S,
                    messageID: A,
                    tool: name,
                    state:
                        status === 'running'
                            ? {
                                  status,
                                  input: { path: 'a.txt' },
                                  time: { start: 0 },
                              }
                            : {
                                  status,
                                  input: { path: 'a.txt' },
                                  output: 'file contents',
                                  time: { start: 0, end: 1000 },
                              },
                },
            },
        })
        const stepFinish = () => ({
            type: 'message.part.updated',
            properties: {
                part: {
                    type: 'step-finish',
                    sessionID: S,
                    messageID: A,
                    tokens: { input: 10, output: 5, reasoning: 0, cache: { read: 0, write: 0 } },
                    cost: 0,
                    reason: 'tool-calls',
                },
            },
        })

        await run([
            {
                type: 'message.updated',
                properties: { info: { role: 'user', id: U, sessionID: S, time: { created: 1 }, agent: 'build' } },
            },
            {
                type: 'message.part.updated',
                properties: { part: { type: 'text', messageID: U, sessionID: S, text: 'read a.txt' } },
            },
            {
                type: 'message.updated',
                properties: {
                    info: {
                        role: 'assistant',
                        id: A,
                        sessionID: S,
                        modelID: 'gpt-5.4-mini',
                        providerID: 'openai',
                        time: { created: 1 },
                    },
                },
            },
            // step 1 — invokes read before edit, but edit completes first
            { type: 'message.part.updated', properties: { part: { type: 'step-start', sessionID: S, messageID: A } } },
            tool('read', 'part-tool-1', 'running'),
            tool('edit', 'part-tool-2', 'running'),
            tool('edit', 'part-tool-2', 'completed'),
            tool('read', 'part-tool-1', 'completed'),
            stepFinish(),
            // step 2 — pure text answer, no tools
            { type: 'message.part.updated', properties: { part: { type: 'step-start', sessionID: S, messageID: A } } },
            {
                type: 'message.part.updated',
                properties: { part: { type: 'text', messageID: A, sessionID: S, text: 'Done.' } },
            },
            stepFinish(),
            { type: 'session.idle', properties: { sessionID: S } },
        ])

        const generations = captured.filter((e) => e.event === '$ai_generation')
        expect(generations).toHaveLength(2)

        // Step 1 reports both tools in invocation order, as a canonical string;
        // step 2 reports none.
        expect(generations[0].properties.$ai_tools_called).toBe('read,edit')
        expect(generations[1].properties.$ai_tools_called).toBeNull()

        // Spans still arrive in completion order and are parented to the same generation.
        const spans = captured.filter((e) => e.event === '$ai_span')
        expect(spans.map((s) => s.properties.$ai_span_name)).toEqual(['edit', 'read'])
        for (const span of spans) {
            expect(span.properties.$ai_parent_id).toBe(generations[0].properties.$ai_span_id)
        }
    })
})

import { describe, it, expect } from 'vitest'
import { redactForPrivacy, serializeAttribute, serializeError } from './utils.js'

describe('redactForPrivacy', () => {
    it('returns value when privacy mode is off', () => {
        expect(redactForPrivacy('hello', false)).toBe('hello')
        expect(redactForPrivacy({ key: 'val' }, false)).toEqual({ key: 'val' })
    })

    it('returns null when privacy mode is on', () => {
        expect(redactForPrivacy('hello', true)).toBeNull()
        expect(redactForPrivacy({ key: 'val' }, true)).toBeNull()
    })
})

describe('serializeAttribute', () => {
    it('serializes simple values', () => {
        expect(serializeAttribute({ a: 1 }, 1000)).toBe('{"a":1}')
        expect(serializeAttribute('hello', 1000)).toBe('hello')
    })

    it('redacts sensitive keys in objects', () => {
        const input = {
            command: 'curl',
            api_key: '[REDACTED]',
            apiKey: '[REDACTED]',
            token: 'my-token',
            password: 'pass123',
            authorization: 'Bearer xyz',
            normal_field: 'visible',
        }
        const result = serializeAttribute(input, 10000)
        expect(result).toContain('[REDACTED]')
        expect(result).not.toContain('sk-secret-123')
        expect(result).not.toContain('another-secret')
        expect(result).not.toContain('my-token')
        expect(result).not.toContain('pass123')
        expect(result).not.toContain('Bearer xyz')
        expect(result).toContain('curl')
        expect(result).toContain('visible')
    })

    it('redacts nested sensitive keys', () => {
        const input = {
            headers: { Authorization: 'Bearer secret' },
            config: { api_key: 'hidden' },
        }
        const result = serializeAttribute(input, 10000)
        expect(result).not.toContain('secret')
        expect(result).not.toContain('hidden')
    })

    it('redacts sensitive values embedded in strings', () => {
        const jsonStr = '{"api_key":"[REDACTED]","name":"test"}'
        const result = serializeAttribute(jsonStr, 10000)
        expect(result).not.toContain('sk-secret-123')
        expect(result).toContain('[REDACTED]')
    })

    it('redacts key=value patterns in strings', () => {
        const cmdOutput = 'config loaded: password=hunter2 host=localhost'
        const result = serializeAttribute(cmdOutput, 10000)
        expect(result).not.toContain('hunter2')
        expect(result).toContain('[REDACTED]')
    })

    it('redacts multi-word bearer token values', () => {
        const header = 'Authorization: Bearer secret-token'
        const result = serializeAttribute(header, 10000)
        expect(result).not.toContain('secret-token')
        expect(result).not.toContain('Bearer')
        expect(result).toContain('[REDACTED]')
    })

    it('redacts header-style secrets with colons in tool output', () => {
        const output = 'HTTP/1.1 200 OK\nAuthorization: Bearer sk-abc123\nContent-Type: text/plain'
        const result = serializeAttribute(output, 10000)
        expect(result).not.toContain('sk-abc123')
        expect(result).toContain('[REDACTED]')
        expect(result).toContain('Content-Type')
    })

    it('truncates long output', () => {
        const longStr = 'a'.repeat(200)
        const result = serializeAttribute(longStr, 50)
        expect(result).not.toBeNull()
        expect(result!.length).toBeLessThan(200)
        expect(result).toContain('...[truncated')
    })

    it('handles circular references', () => {
        const obj: Record<string, unknown> = { name: 'test' }
        obj.self = obj
        const result = serializeAttribute(obj, 1000)
        expect(result).toContain('[Circular]')
        expect(result).toContain('test')
    })

    it('handles deep nesting', () => {
        let obj: Record<string, unknown> = { value: 'deep' }
        for (let i = 0; i < 20; i++) {
            obj = { nested: obj }
        }
        const result = serializeAttribute(obj, 10000)
        expect(result).toContain('[DepthLimit]')
    })

    it('returns null for undefined and null', () => {
        expect(serializeAttribute(undefined, 1000)).toBeNull()
        expect(serializeAttribute(null, 1000)).toBeNull()
    })
})

describe('serializeError', () => {
    it('serializes error objects to JSON', () => {
        const error = { name: 'UnknownError', data: { message: 'boom' } }
        const result = serializeError(error)
        expect(result).toBe('{"name":"UnknownError","data":{"message":"boom"}}')
    })

    it('returns null for undefined', () => {
        expect(serializeError(undefined)).toBeNull()
    })

    it('handles circular references via redaction', () => {
        const circular: Record<string, unknown> = { name: 'BadError' }
        circular.self = circular
        const result = serializeError(circular as { name: string; data?: Record<string, unknown> })
        expect(result).toContain('BadError')
        expect(result).toContain('[Circular]')
    })

    it('redacts sensitive keys in error data', () => {
        const error = { name: 'AuthError', data: { api_key: '[REDACTED]', message: 'failed' } }
        const result = serializeError(error)
        expect(result).not.toContain('sk-secret-123')
        expect(result).toContain('[REDACTED]')
        expect(result).toContain('failed')
    })
})

import { describe, it, expect } from 'vitest'
import { buildAiGeneration, buildAiSpan, buildAiTrace, mapStopReason } from './events.js'
import type { PluginConfig, TraceState, AssistantInfo } from './types.js'
import type { StepFinishPart, ToolStateCompleted, ToolStateError } from '@opencode-ai/sdk'

const defaultConfig: PluginConfig = {
    apiKey: 'test-key',
    host: 'https://us.i.posthog.com',
    privacyMode: false,
    enabled: true,
    distinctId: 'test-host',
    projectName: 'my-project',
    tags: {},
    maxAttributeLength: 12000,
}

const privacyConfig: PluginConfig = {
    ...defaultConfig,
    privacyMode: true,
}

const configWithTags: PluginConfig = {
    ...defaultConfig,
    tags: { team: 'platform', env: 'staging' },
}

function makeStepFinish(overrides?: Partial<StepFinishPart>): StepFinishPart {
    return {
        id: 'part-1',
        sessionID: 'session-1',
        messageID: 'msg-1',
        type: 'step-finish',
        reason: 'stop',
        cost: 0.003,
        tokens: {
            input: 100,
            output: 50,
            reasoning: 10,
            cache: { read: 5, write: 3 },
        },
        ...overrides,
    }
}

function makeTrace(overrides?: Partial<TraceState>): TraceState {
    return {
        traceId: 'trace-123',
        sessionId: 'session-1',
        startTime: Date.now() - 5000,
        totalInputTokens: 500,
        totalOutputTokens: 200,
        totalCost: 0.01,
        hadError: false,
        agentName: 'my-project',
        currentGenerationSpanId: 'gen-span-1',
        userPrompt: 'Hello',
        lastAssistantText: 'Hi there!',
        stepInputMessages: [{ role: 'user', content: 'Hello' }],
        stepInputSnapshot: [{ role: 'user', content: 'Hello' }],
        stepAssistantText: 'Hi there!',
        stepToolCalls: [],
        stepToolCallIds: new Set<string>(),
        messageIds: new Set<string>(),
        ...overrides,
    }
}

function makeAssistantInfo(overrides?: Partial<AssistantInfo>): AssistantInfo {
    return {
        messageID: 'msg-1',
        modelID: 'claude-sonnet-4-20250514',
        providerID: 'anthropic',
        ...overrides,
    }
}

describe('mapStopReason', () => {
    it('maps known stop reasons', () => {
        expect(mapStopReason('stop')).toBe('stop')
        expect(mapStopReason('length')).toBe('length')
        expect(mapStopReason('tool-calls')).toBe('tool_calls')
        expect(mapStopReason('error')).toBe('error')
    })

    it('returns null for undefined', () => {
        expect(mapStopReason(undefined)).toBeNull()
    })

    it('passes through unknown reasons', () => {
        expect(mapStopReason('custom_reason')).toBe('custom_reason')
    })
})

describe('buildAiGeneration', () => {
    it('builds generation event with all fields', () => {
        const part = makeStepFinish()
        const trace = makeTrace()
        const assistant = makeAssistantInfo()

        const result = buildAiGeneration(part, assistant, trace, defaultConfig)

        expect(result.event).toBe('$ai_generation')
        expect(result.distinctId).toBe('test-host')
        expect(result.properties.$ai_model).toBe('claude-sonnet-4-20250514')
        expect(result.properties.$ai_provider).toBe('anthropic')
        expect(result.properties.$ai_input_tokens).toBe(100)
        expect(result.properties.$ai_output_tokens).toBe(50)
        expect(result.properties.$ai_reasoning_tokens).toBe(10)
        expect(result.properties.cache_read_input_tokens).toBe(5)
        expect(result.properties.cache_creation_input_tokens).toBe(3)
        expect(result.properties.$ai_total_cost_usd).toBe(0.003)
        expect(result.properties.$ai_stop_reason).toBe('stop')
        expect(result.properties.$ai_is_error).toBe(false)
        expect(result.properties.$ai_trace_id).toBe('trace-123')
        expect(result.properties.$ai_span_id).toBe('gen-span-1')
        expect(result.properties.$ai_session_id).toBe('session-1')
        expect(result.properties.$ai_lib).toBe('posthog-opencode')
        expect(result.properties.$ai_framework).toBe('opencode')
        expect(result.properties.$ai_project_name).toBe('my-project')
        expect(result.properties.$ai_agent_name).toBe('my-project')
    })

    it('uses pre-allocated span ID from trace', () => {
        const trace = makeTrace({ currentGenerationSpanId: 'pre-allocated-id' })
        const result = buildAiGeneration(makeStepFinish(), makeAssistantInfo(), trace, defaultConfig)
        expect(result.properties.$ai_span_id).toBe('pre-allocated-id')
    })

    it('falls back to random UUID when no pre-allocated span ID', () => {
        const trace = makeTrace({ currentGenerationSpanId: undefined })
        const result = buildAiGeneration(makeStepFinish(), makeAssistantInfo(), trace, defaultConfig)
        expect(result.properties.$ai_span_id).toBeDefined()
        expect(typeof result.properties.$ai_span_id).toBe('string')
    })

    it('includes input and output content from step snapshot', () => {
        const trace = makeTrace({
            userPrompt: 'What is 2+2?',
            stepInputSnapshot: [{ role: 'user', content: 'What is 2+2?' }],
            stepAssistantText: '4',
            lastAssistantText: '4',
        })
        const result = buildAiGeneration(makeStepFinish(), makeAssistantInfo(), trace, defaultConfig)
        expect(result.properties.$ai_input).toEqual([{ role: 'user', content: 'What is 2+2?' }])
        expect(result.properties.$ai_output_choices).toEqual([{ role: 'assistant', content: '4' }])
    })

    it('includes prior tool results in input for multi-step generations', () => {
        const trace = makeTrace({
            // Snapshot was taken at step-start, before current-step tools ran
            stepInputSnapshot: [
                { role: 'user', content: 'Read the file' },
                { role: 'tool', content: '[read] file contents here' },
            ],
            stepAssistantText: 'I read the file.',
        })
        const result = buildAiGeneration(makeStepFinish(), makeAssistantInfo(), trace, defaultConfig)
        expect(result.properties.$ai_input).toEqual([
            { role: 'user', content: 'Read the file' },
            { role: 'tool', content: '[read] file contents here' },
        ])
        expect(result.properties.$ai_output_choices).toEqual([{ role: 'assistant', content: 'I read the file.' }])
    })

    it('redacts content in privacy mode', () => {
        const trace = makeTrace()
        const result = buildAiGeneration(makeStepFinish(), makeAssistantInfo(), trace, privacyConfig)
        expect(result.properties.$ai_input).toBeNull()
        expect(result.properties.$ai_output_choices).toBeNull()
    })

    it('reports the tools called during the step, in call order', () => {
