import { hostname } from 'node:os'
import { basename } from 'node:path'
import type { PluginConfig } from './types.js'

export function loadConfig(): PluginConfig {
    const tags: Record<string, string> = {}
    const tagsEnv = process.env.POSTHOG_TAGS
    if (tagsEnv) {
        for (const pair of tagsEnv.split(',')) {
            const colonIdx = pair.indexOf(':')
            if (colonIdx > 0) {
                const key = pair.slice(0, colonIdx).trim()
                const val = pair.slice(colonIdx + 1).trim()
                if (key.length > 0 && val.length > 0) {
                    tags[key] = val
                }
            }
        }
    }

    let distinctId = process.env.POSTHOG_DISTINCT_ID
    if (!distinctId) {
        try {
            distinctId = hostname()
        } catch {
            distinctId = 'opencode-user'
        }
    }

    return {
        apiKey: [REDACTED] ?? '',
        host: process.env.POSTHOG_HOST ?? 'https://us.i.posthog.com',
        privacyMode: process.env.POSTHOG_PRIVACY_MODE === 'true',
        enabled: process.env.POSTHOG_ENABLED !== 'false',
        distinctId,
        projectName: process.env.POSTHOG_PROJECT_NAME || basename(process.cwd()) || 'opencode-project',
        tags,
        maxAttributeLength: parseInt(process.env.POSTHOG_MAX_ATTRIBUTE_LENGTH ?? '12000', 10) || 12000,
    }
}

const SENSITIVE_KEY_PATTERN = /api[-_]?key|token|secret|password|authorization|credential|private[-_]?key/i

/**
 * Patterns to detect sensitive values embedded in strings.
 *
 * JSON-style: `"api_key": "[REDACTED]"` or `"token":"abc"`
 * Matches the full `"key":"value"` including the quoted value.
 */
const SENSITIVE_JSON_PATTERN =
    /"(?:api[-_]?key|token|secret|password|authorization|credential|private[-_]?key)"\s*:\s*"[^"]*"/gi

/**
 * Header/env-style: `Authorization: Bearer secret-token` or `password=hunter2`
 * Matches the key and everything to the next comma, semicolon, newline, or
 * end-of-string so multi-word values like `Bearer xyz` are fully consumed.
 */
const SENSITIVE_KV_PATTERN =
    /(?:api[-_]?key|token|secret|password|authorization|credential|private[-_]?key)\s*[=:]\s*[^\n,;]*/gi

/**
 * Redact sensitive values found inline in a string. Handles both JSON-like
 * `"key":"value"` patterns and `key=value` / `key: value` patterns.
 */
function redactStringValues(str: string): string {
    return str.replace(SENSITIVE_JSON_PATTERN, '[REDACTED]').replace(SENSITIVE_KV_PATTERN, '[REDACTED]')
}

function redactSensitive(value: unknown, seen: WeakSet<object>, depth: number): unknown {
    if (depth > 8) return '[DepthLimit]'
    if (value === null || value === undefined) return value
    if (typeof value === 'string') return redactStringValues(value)
    if (typeof value !== 'object') return value
    if (seen.has(value)) return '[Circular]'
    seen.add(value)

    if (Array.isArray(value)) {
        return value.map((item) => redactSensitive(item, seen, depth + 1))
    }

    const output: Record<string, unknown> = {}
    for (const [key, nested] of Object.entries(value)) {
        if (SENSITIVE_KEY_PATTERN.test(key)) {
            output[key] = '[REDACTED]'
        } else {
            output[key] = redactSensitive(nested, seen, depth + 1)
        }
    }
    return output
}

function truncate(value: string, maxLength: number): string {
    if (maxLength <= 0) return ''
    if (value.length <= maxLength) return value
    const omitted = value.length - maxLength
    return `${value.slice(0, maxLength)}...[truncated ${omitted} chars]`
}

export function serializeAttribute(value: unknown, maxLength: number): string | null {
    if (value === undefined || value === null) return null

    const redacted = redactSensitive(value, new WeakSet<object>(), 0)

    if (typeof redacted === 'string') {
        return truncate(redacted, maxLength)
    }

    try {
        const json = JSON.stringify(redacted)
        if (json === undefined) return null
        return truncate(json, maxLength)
    } catch {
        return '[Unserializable]'
    }
}

export function redactForPrivacy<T>(value: T, privacyMode: boolean): T | null {
    return privacyMode ? null : value
}

export function serializeError(
    error: { name: string; data?: Record<string, unknown> } | undefined,
    maxLength: number = 12000
): string | null {
    if (!error) return null
    return serializeAttribute(error, maxLength)
}

import { randomUUID } from 'node:crypto'
import type { StepFinishPart, ToolStateCompleted, ToolStateError } from '@opencode-ai/sdk'
import type { AssistantInfo, PluginConfig, TraceState } from './types.js'
import { redactForPrivacy, serializeAttribute, serializeError } from './utils.js'
import { VERSION } from './version.js'

export interface CaptureEvent {
    event: string
    distinctId: string
    properties: Record<string, unknown>
}

const STOP_REASON_MAP: Record<string, string> = {
    stop: 'stop',
    length: 'length',
    'tool-calls': 'tool_calls',
    error: 'error',
}

export function mapStopReason(reason: string | undefined): string | null {
    if (!reason) return null
    return STOP_REASON_MAP[reason] ?? reason
}

export function buildAiGeneration(
    part: StepFinishPart,
    assistantInfo: AssistantInfo | undefined,
    trace: TraceState,
    config: PluginConfig
): CaptureEvent {
    // Use the span ID allocated at step-start so tool spans emitted
    // during this step already reference the correct parent.
    const spanId = trace.currentGenerationSpanId ?? randomUUID()

    // Use the snapshot taken at step-start, which contains context the model
    // actually saw (user prompt + prior tool results), not current-step tools.
    const inputMessages = redactForPrivacy(
        trace.stepInputSnapshot.length > 0 ? trace.stepInputSnapshot : null,
        config.privacyMode
    )

    const outputChoices = redactForPrivacy(
        trace.stepAssistantText ? [{ role: 'assistant', content: trace.stepAssistantText }] : null,
        config.privacyMode
    )

    return {
        event: '$ai_generation',
        distinctId: config.distinctId,
        properties: {
            $ai_trace_id: trace.traceId,
            $ai_session_id: trace.sessionId,
            $ai_span_id: spanId,
            $ai_model: assistantInfo?.modelID ?? 'unknown',
            $ai_provider: assistantInfo?.providerID ?? 'unknown',

            $ai_input_tokens: part.tokens.input,
            $ai_output_tokens: part.tokens.output,
            $ai_reasoning_tokens: part.tokens.reasoning,
            cache_read_input_tokens: part.tokens.cache.read,
            cache_creation_input_tokens: part.tokens.cache.write,

            $ai_total_cost_usd: part.cost,
            $ai_stop_reason: mapStopReason(part.reason),

            $ai_input: inputMessages,
            $ai_output_choices: outputChoices,

            // Tool calls are emitted as $ai_span events too, but PostHog only extracts
            // tool usage from $ai_generation, so the Tools view stays empty unless the
            // names are reported here as a canonical comma-separated string.
            // Names only — no arguments — so this carries no more than $ai_span_name,
            // which is already sent unredacted in privacy mode.
            $ai_tools_called: trace.stepToolCalls.length > 0 ? trace.stepToolCalls.join(',') : null,

            $ai_is_error: !!assistantInfo?.error,
            $ai_error: serializeError(assistantInfo?.error, config.maxAttributeLength),

            $ai_lib: 'posthog-opencode',
            $ai_lib_version: VERSION,
            $ai_framework: 'opencode',
            $ai_project_name: config.projectName,
            $ai_agent_name: trace.agentName ?? config.projectName,
            ...config.tags,
        },
    }
}

export function buildAiSpan(
    toolName: string,
    toolState: ToolStateCompleted | ToolStateError,
    trace: TraceState,
    config: PluginConfig
): CaptureEvent {
    const spanId = randomUUID()
    const latency = (toolState.time.end - toolState.time.start) / 1000
    const isError = toolState.status === 'error'

    const inputState = redactForPrivacy(
        serializeAttribute(toolState.input, config.maxAttributeLength),
        config.privacyMode
    )

    let outputState: string | null = null
    if (!config.privacyMode) {
        if (toolState.status === 'completed') {
            outputState = serializeAttribute(toolState.output, config.maxAttributeLength)
        } else {
            outputState = serializeAttribute(toolState.error, config.maxAttributeLength)
        }
    }

    return {
        event: '$ai_span',
        distinctId: config.distinctId,
        properties: {
            $ai_trace_id: trace.traceId,
            $ai_session_id: trace.sessionId,
            $ai_span_id: spanId,
            $ai_parent_id: trace.currentGenerationSpanId ?? null,
            $ai_span_name: toolName,

            $ai_latency: latency,

            $ai_input_state: inputState,
            $ai_output_state: outputState,

            $ai_is_error: isError,
            $ai_error: isError
                ? serializeAttribute((toolState as ToolStateError).error, config.maxAttributeLength)
                : null,

            $ai_lib: 'posthog-opencode',
            $ai_lib_version: VERSION,
            $ai_framework: 'opencode',
            $ai_project_name: config.projectName,
            $ai_agent_name: trace.agentName ?? config.projectName,
            ...config.tags,
        },
    }
}

export function buildAiTrace(trace: TraceState, config: PluginConfig): CaptureEvent {
    const latency = (Date.now() - trace.startTime) / 1000

    return {
        event: '$ai_trace',
        distinctId: config.distinctId,
        properties: {
            $ai_trace_id: trace.traceId,
            $ai_session_id: trace.sessionId,
            $ai_latency: latency,
            $ai_span_name: config.projectName,

            $ai_input_state: redactForPrivacy(trace.userPrompt ?? null, config.privacyMode),
            $ai_output_state: redactForPrivacy(trace.lastAssistantText ?? null, config.privacyMode),

            $ai_total_input_tokens: trace.totalInputTokens,
            $ai_total_output_tokens: trace.totalOutputTokens,

            $ai_is_error: trace.hadError,
            $ai_error: trace.lastError ? serializeAttribute(trace.lastError, config.maxAttributeLength) : null,

            $ai_lib: 'posthog-opencode',
            $ai_lib_version: VERSION,
            $ai_framework: 'opencode',
            $ai_project_name: config.projectName,
            $ai_agent_name: trace.agentName ?? config.projectName,
            ...config.tags,
        },
    }
}

import type { Plugin } from '@opencode-ai/plugin'
import type {
    Event,
    AssistantMessage,
    StepStartPart,
    StepFinishPart,
    ToolPart,
    TextPart,
    ToolStateCompleted,
    ToolStateError,
} from '@opencode-ai/sdk'
import { PostHog } from 'posthog-node'
import { randomUUID } from 'node:crypto'
import { loadConfig, serializeAttribute } from './utils.js'
import { buildAiGeneration, buildAiSpan, buildAiTrace } from './events.js'
import type { AssistantInfo, TraceState } from './types.js'
import type { CaptureEvent } from './events.js'

export const PostHogPlugin: Plugin = async () => {
    const config = loadConfig()

    if (!config.enabled || !config.apiKey) return {}

    const client = new PostHog(config.apiKey, {
        host: config.host,
        flushAt: 20,
        flushInterval: 10_000,
    })

    function safeCapture(event: CaptureEvent) {
        try {
            client.capture({
                distinctId: event.distinctId,
                event: event.event,
                properties: event.properties,
            })
        } catch {
            // never crash the host
        }
    }

    // State: sessionID -> trace state
    const traces = new Map<string, TraceState>()
    // State: messageID -> role for correlating parts to messages
    const messageRoles = new Map<string, 'user' | 'assistant'>()
    // State: messageID -> assistant info
    const assistantMessages = new Map<string, AssistantInfo>()

    function getOrCreateTrace(sessionId: string): TraceState {
        let trace = traces.get(sessionId)
        if (!trace) {
            trace = {
                traceId: randomUUID(),
                sessionId,
                startTime: Date.now(),
                totalInputTokens: 0,
                totalOutputTokens: 0,
                totalCost: 0,
                hadError: false,
                stepInputMessages: [],
                stepInputSnapshot: [],
                stepToolCalls: [],
                stepToolCallIds: new Set(),
                messageIds: new Set(),
            }
            traces.set(sessionId, trace)
        }
        return trace
    }

    function handleMessageUpdated(event: Event) {
        if (event.type !== 'message.updated') return
        const msg = event.properties.info

        if (msg.role === 'user') {
            // OpenCode emits `message.updated` for the same user message several
            // times per turn. Only start a new trace the first time we see a given
            // user message — a repeat update must not reset the trace, or it wipes
            // the captured prompt ($ai_input) and the assistant model info for the
            // turn (both are accumulated on the trace before step-finish fires).
            if (messageRoles.get(msg.id) === 'user') return

            // New user message → new trace
            const trace: TraceState = {
                traceId: randomUUID(),
                sessionId: msg.sessionID,
                startTime: msg.time.created,
                totalInputTokens: 0,
                totalOutputTokens: 0,
                totalCost: 0,
                hadError: false,
                agentName: msg.agent,
                stepInputMessages: [],
                stepInputSnapshot: [],
                stepToolCalls: [],
                stepToolCallIds: new Set(),
                messageIds: new Set([msg.id]),
            }
            traces.set(msg.sessionID, trace)
            messageRoles.set(msg.id, 'user')
        } else if (msg.role === 'assistant') {
            const assistant = msg as AssistantMessage
            messageRoles.set(assistant.id, 'assistant')

            const info: AssistantInfo = {
                messageID: assistant.id,
                modelID: assistant.modelID,
                providerID: assistant.providerID,
                error: assistant.error,
            }
            assistantMessages.set(assistant.id, info)

            // Update trace with current assistant info
            const trace = getOrCreateTrace(assistant.sessionID)
            trace.messageIds.add(assistant.id)
            trace.currentAssistantMsg = info
            if (assistant.error) {
                trace.hadError = true
                trace.lastError = serializeAttribute(assistant.error, config.maxAttributeLength) ?? assistant.error.name
            }
        }
    }

    function handlePartUpdated(event: Event) {
        if (event.type !== 'message.part.updated') return
        const part = event.properties.part

        switch (part.type) {
            case 'text':
                handleTextPart(part)
                break
            case 'step-start':
                handleStepStart(part)
                break
            case 'step-finish':
                handleStepFinish(part)
                break
            case 'tool':
                handleToolPart(part)
                break
        }
    }

    function handleTextPart(part: TextPart) {
        const role = messageRoles.get(part.messageID)
        if (!role) return

        const trace = traces.get(part.sessionID)
        if (!trace) return

        if (role === 'user') {
            trace.userPrompt = part.text
            trace.stepInputMessages.push({ role: 'user', content: part.text })
        } else if (role === 'assistant') {
            trace.lastAssistantText = part.text
            trace.stepAssistantText = part.text
        }
    }

    function handleStepStart(part: StepStartPart) {
        const trace = traces.get(part.sessionID)
        if (!trace) return
        // Allocate the generation span ID eagerly so that tool spans
        // emitted during this step can reference it as their parent.
        trace.currentGenerationSpanId = randomUUID()
        // Snapshot current input messages before tools run, so the
        // generation reports only what the model saw as input, not
        // the tool results from the current step.
        trace.stepInputSnapshot = [...trace.stepInputMessages]
        // Reset per-step assistant text for the new generation
        trace.stepAssistantText = undefined
        // Reset per-step tool calls; they are attributed to the generation
        // whose span ID was just allocated above.
        trace.stepToolCalls = []
        trace.stepToolCallIds = new Set()
    }

    function handleStepFinish(part: StepFinishPart) {
        const trace = traces.get(part.sessionID)
        if (!trace) return

        // The step belongs to a specific assistant message; prefer that message's
        // model/provider info (looked up by messageID) over the trace's "current"
        // assistant pointer, which can lag behind streaming updates.
        const assistantInfo = assistantMessages.get(part.messageID) ?? trace.currentAssistantMsg

        // Accumulate tokens and cost
        trace.totalInputTokens += part.tokens.input
        trace.totalOutputTokens += part.tokens.output
        trace.totalCost += part.cost

        const generation = buildAiGeneration(part, assistantInfo, trace, config)
        safeCapture(generation)
    }

    function handleToolPart(part: ToolPart) {
        const trace = traces.get(part.sessionID)
        if (!trace) return

        // Record invocation order as tools start. Terminal updates can arrive in
        // a different order for parallel calls, and each call emits multiple updates.
        if (part.state.status !== 'pending' && !trace.stepToolCallIds.has(part.callID)) {
            trace.stepToolCallIds.add(part.callID)
            trace.stepToolCalls.push(part.tool)
        }

        if (part.state.status !== 'completed' && part.state.status !== 'error') return

        const toolState = part.state as ToolStateCompleted | ToolStateError
        const span = buildAiSpan(part.tool, toolState, trace, config)
        safeCapture(span)

        // Feed tool result into step input so subsequent generations include
        // the tool context the model actually saw. Redact and truncate to
        // match the treatment applied to $ai_span fields.
        if (toolState.status === 'completed') {
            const redacted = serializeAttribute(toolState.output, config.maxAttributeLength) ?? ''
            trace.stepInputMessages.push({
                role: 'tool',
                content: `[${part.tool}] ${redacted}`,
            })
        } else {
            const redacted = serializeAttribute(toolState.error, config.maxAttributeLength) ?? ''
            trace.stepInputMessages.push({
                role: 'tool',
                content: `[${part.tool}] ERROR: ${redacted}`,
            })
            trace.hadError = true
            trace.lastError = toolState.error
        }
    }

    async function handleSessionIdle(event: Event) {
        if (event.type !== 'session.idle') return

        const sessionId = event.properties.sessionID
        const trace = traces.get(sessionId)
        if (!trace) return

        const traceEvent = buildAiTrace(trace, config)
        safeCapture(traceEvent)

        try {
            await client.flush()
        } catch {
            // ignore flush errors
        }

        // Clean up per-message state for this trace
        for (const msgId of trace.messageIds) {
            messageRoles.delete(msgId)
            assistantMessages.delete(msgId)
        }
        traces.delete(sessionId)
    }

    function handleSessionError(event: Event) {
        if (event.type !== 'session.error') return

        const sessionId = event.properties.sessionID
        if (!sessionId) return

        const trace = traces.get(sessionId)
        if (trace) {
            trace.hadError = true
            if (event.properties.error) {
                trace.lastError =
                    serializeAttribute(event.properties.error, config.maxAttributeLength) ?? 'unknown error'
            }
        }
    }

    let disposed = false

    return {
        event: async ({ event }) => {
            try {
                switch (event.type) {
                    case 'message.updated':
                        handleMessageUpdated(event)
                        break
                    case 'message.part.updated':
                        handlePartUpdated(event)
                        break
                    case 'session.idle':
                        await handleSessionIdle(event)
                        break
                    case 'session.error':
                        handleSessionError(event)
                        break
                }
            } catch {
                // never crash OpenCode
            }
        },
        // Flush and shut down the PostHog client when OpenCode tears the plugin
        // down. posthog-node's flush() resolves before the HTTP send actually
        // completes, so a short-lived `opencode run` invocation would otherwise
        // exit and drop its final events. shutdown() drains all pending events and
        // awaits the network round-trip. OpenCode awaits this dispose hook during
        // teardown (it is registered as a scope finalizer).
        dispose: async () => {
            if (disposed) return
            disposed = true
            try {
                await client.shutdown()
            } catch {
                // never crash OpenCode
            }
        },
    }
}
